package bo.soboce.comedor;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import com.google.zxing.*;
import com.google.zxing.common.BitMatrix;
import com.google.zxing.integration.android.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** One app for master, administrators and operators; accounts are not worker identities. */
public final class StaffActivity extends Activity {
 private final ExecutorService executor=Executors.newSingleThreadExecutor();
 private PeerConfig config;private StaffAccess auth;private String company,scanMode="",replaceId="";private LinearLayout page;private TextView state;private boolean busy;private JSONObject editing;private android.os.CancellationSignal biometric;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);try{
  company=getIntent().getStringExtra("company");if(company==null)company=Companies.current(this);config=new PeerConfig(new Vault(this,company).get("peerConfig"));auth=StaffAccess.attach(this,config);PeerConfig.require(auth!=null,"Esta instalación no tiene configuradas las cuentas.");
  if(auth.ready()){if(getIntent().getBooleanExtra("manage",false))dashboard();else complete();}else login();
 }catch(Exception e){screen("Acceso del personal","Se conservan los trabajadores y las entregas. No crees otra cuenta ni borres datos si no se pudo leer tu acceso.");error(e.getMessage());button("Reintentar",this::recreate);button("Volver",this::finish);}}
 private void reload()throws Exception {auth=new StaffAccess(this,config);}
 private void screen(String title,String subtitle){ScrollView s=new ScrollView(this);s.setBackgroundColor(Design.BG);page=Design.column(this);page.setPadding(24,30,24,30);s.addView(page);setContentView(s);s.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(0,in.getSystemWindowInsetTop(),0,in.getSystemWindowInsetBottom());return in;});label((company==null?"COLBERT":company.toUpperCase(Locale.ROOT))+" / ACCESO PERSONAL",12,Design.BLUE);label(title,28,Design.INK);label(subtitle,15,Design.MUTED);state=label("",14,Design.RED);}
 private TextView label(String text,int size,int color){TextView v=Design.text(this,text,size,color,size>=20);v.setPadding(0,10,0,10);page.addView(v);return v;}
 private EditText field(String hint,String text,boolean pin){EditText v=new EditText(this);v.setHint(hint);v.setText(text);v.setSingleLine(true);if(pin){v.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD);v.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(6)});}page.addView(v,new LinearLayout.LayoutParams(-1,Design.dp(this,58)));return v;}
 private void button(String title,Runnable run){Button b=Design.button(this,title,Design.BLUE,Color.WHITE,()->{if(!busy)run.run();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=10;page.addView(b,p);}
 private void error(String message){if(state!=null)state.setText(message==null?"No se pudo completar. Vuelve a intentarlo.":message);}
 interface Work {JSONObject run()throws Exception;}
 private void task(Work work,java.util.function.Consumer<JSONObject> done){if(busy)return;busy=true;state.setText("Comprobando autorización…");executor.execute(()->{JSONObject reply=null;String problem=null;try{reply=work.run();}catch(Exception e){problem=e instanceof java.io.IOException?"No se confirmó la conexión. Tus datos y permisos guardados se conservan.":e.getMessage();}JSONObject r=reply;String p=problem;runOnUiThread(()->{busy=false;if(isFinishing()||isDestroyed())return;if(p!=null)error(p);else{state.setText("");done.accept(r);}});});}
 private void login(){try{
  JSONArray profiles=auth.profiles();
  screen("Iniciar sesión","Si ya tienes cuenta, entra con tu PIN. Actualizar la app no requiere crear otra cuenta.");
  if(profiles.length()==0)label("No hay un perfil guardado en esta instalación. Si el maestro ya te registró, utiliza Recuperar cuenta existente.",15,Design.INK);
  else label("CUENTAS EN ESTE TELÉFONO",13,Design.BLUE);
  for(int i=0;i<profiles.length();i++){JSONObject p=profiles.getJSONObject(i);String id=p.getString("profile");button("Entrar · "+p.getString("name"),()->{try{auth.select(id);reload();pin();}catch(Exception e){error(e.getMessage());}});}
  button("Ya tengo cuenta · recuperar acceso",this::recoverProfile);button("Solicitar cuenta nueva",this::createProfile);button("Cambiar empresa",this::switchCompany);button("Volver",this::finish);
 }catch(Exception e){error(e.getMessage());}}
 private void createProfile(){prepareProfile(false);}
 private void recoverProfile(){prepareProfile(true);}
 private void prepareProfile(boolean recovery){screen(recovery?"Recuperar cuenta existente":"Solicitar cuenta nueva",recovery?"El maestro vinculará este teléfono a tu cuenta que ya existe. Se conserva tu identificador e historial. Tu nombre por sí solo no permite entrar.":"Solo el maestro puede crear administradores y encargados. Primero prepara tu PIN y solicita su autorización.");EditText name=field("Tu nombre completo","",false),pin=field(recovery?"PIN para entrar en este teléfono":"PIN personal de 6 números","",true),again=field("Repite tu PIN","",true);
  button(recovery?"Preparar recuperación":"Preparar solicitud",()->{String n=name.getText().toString(),p=pin.getText().toString(),repeat=again.getText().toString();task(()->{PeerConfig.require(p.equals(repeat),"Los PIN no coinciden.");auth.create(n,p,recovery?"recover":"new");reload();return new JSONObject();},r->pending());});button("Volver a iniciar sesión",this::login);
 }
 private void pin(){try{screen("Hola, "+auth.local().getString("name"),"Desbloquea tu perfil para comenzar el turno.");EditText input=field("PIN de 6 números","",true);
  button("Entrar",()->{String pin=input.getText().toString();task(()->{auth.unlock(pin);try{auth.refresh(true);}catch(java.io.IOException ignored){/* A valid cached account and paid lease remain usable offline. */}return new JSONObject();},r->{if(auth.authorized()){if(getIntent().getBooleanExtra("manage",false))dashboard();else complete();}else pending();});});
  if(android.os.Build.VERSION.SDK_INT>=28&&auth.profiles().length()==1&&auth.global.get("staffBiometric:"+auth.profile).equals("yes"))button("Usar huella o biometría del teléfono",this::biometric);
  button("Cambiar de perfil",this::login);button("Olvidé mi PIN",this::recoverProfile);
 }catch(Exception e){error(e.getMessage());}}
 @android.annotation.TargetApi(28) private void biometric(){biometric=new android.os.CancellationSignal();new android.hardware.biometrics.BiometricPrompt.Builder(this).setTitle("Desbloquear cuenta personal").setSubtitle("Usa el PIN si este teléfono es compartido").setNegativeButton("Usar PIN",getMainExecutor(),(d,w)->{}).build().authenticate(biometric,getMainExecutor(),new android.hardware.biometrics.BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(android.hardware.biometrics.BiometricPrompt.AuthenticationResult result){StaffAccess.unlocked=auth.profile;task(()->{try{auth.refresh(true);}catch(java.io.IOException ignored){}return new JSONObject();},r->{if(auth.authorized())complete();else pending();});}@Override public void onAuthenticationError(int code,CharSequence text){error(text.toString());}});}
 private void pending(){try{
  boolean recovering=auth.local().optString("intent").equals("recover");
  screen(recovering?"Recuperar mi cuenta":"Autorizar este teléfono",auth.local().getString("name")+" · Los trabajadores, QR y consumos que ya tenías siguen guardados.");
  if(recovering)label("El maestro debe elegir tu cuenta existente al recibir esta solicitud. No necesitas que cree otra cuenta.",15,Design.INK);
  if(!auth.certificate().isEmpty()&&!auth.authorized())label("Cuenta desactivada o equipo reemplazado. Solo el maestro puede cambiar ese permiso.",15,Design.RED);
  button("Mostrar solicitud al maestro",()->task(()->auth.remote("request",new JSONObject().put("name",auth.local().getString("name")).put("device",config.device).put("intent",recovering?"recover":"new")),r->{try{if(r.optBoolean("alreadyKnown")){check();return;}String qr=StaffProtocol.REQUEST+new JSONObject().put("cluster",config.cluster).put("request",r.getString("id")).put("expires",r.getLong("expires")).toString();screen(recovering?"Solicitud de recuperación":"Solicitud de acceso",recovering?"El maestro escanea o pega esta solicitud y selecciona tu cuenta existente. Conserva tus permisos; reemplaza el acceso anterior. Vence en diez minutos.":"El maestro debe escanear este QR en Encargados y permisos. Dura diez minutos y solo autoriza este perfil y teléfono.");showQr(qr);button("Copiar solicitud para el maestro",()->copyRequest(qr));button("Compartir solicitud QR",()->shareRequest(qr));button("Ya me autorizaron · comprobar",this::check);button("Volver",this::pending);}catch(Exception e){error(e.getMessage());}}));
  button("Ya me autorizaron · comprobar",this::check);button("Activar o recuperar usuario maestro",()->scan("master"));button("Cambiar de perfil",this::login);button("Cambiar empresa",this::switchCompany);
 }catch(Exception e){error(e.getMessage());}}
 private void switchCompany(){try{PeerConfig.require(new Vault(this,company).get("pending").isEmpty(),"Hay una entrega pendiente. Conserva esta empresa hasta comprobarla.");stopService(new Intent(this,PeerService.class));Handler h=new Handler(getMainLooper());h.postDelayed(new Runnable(){int tries;public void run(){if(isFinishing()||isDestroyed())return;if(PeerService.engine!=null){if(++tries<40){h.postDelayed(this,250);return;}error("La red aún se está cerrando. Vuelve a intentar.");return;}try{Companies.select(StaffActivity.this,company.equals("soboce")?"frigor":"soboce");startActivity(new Intent(StaffActivity.this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();}catch(Exception e){error(e.getMessage());}}},250);}catch(Exception e){error(e.getMessage());}}
 private void check(){task(()->auth.remote("status",new JSONObject()),r->{if(auth.authorized())complete();else error(auth.certificate().isEmpty()?"El maestro debe autorizar o recuperar tu cuenta en "+company.toUpperCase(Locale.ROOT)+".":"Esta cuenta está desactivada o su teléfono fue reemplazado. Solicita al maestro revisar tu cuenta existente.");});}
 private void complete(){setResult(RESULT_OK);finish();}
 private void dashboard(){try{
  JSONObject g=auth.grant();screen("Mi cuenta",g.getString("name")+" · "+role(g.getString("role")));label("Plantas: "+g.getJSONArray("plants").join(", ").replace("\"",""),15,Design.INK);
  if(auth.master()){button("Encargados y permisos",this::list);button("Autorizar teléfono · escanear QR",()->{editing=null;scan("grant");});button("Autorizar solicitud copiada",this::pasteRequest);}
  if(android.os.Build.VERSION.SDK_INT>=28&&auth.profiles().length()==1){CheckBox personal=new CheckBox(this);personal.setText("Es mi teléfono personal: permitir biometría");personal.setChecked(auth.global.get("staffBiometric:"+auth.profile).equals("yes"));page.addView(personal);personal.setOnCheckedChangeListener((b,on)->{try{auth.require("people","");auth.global.put("staffBiometric:"+auth.profile,on?"yes":"no");}catch(Exception e){error(e.getMessage());}});label("La biometría acepta las huellas o rostros registrados en Android. En teléfonos compartidos utiliza un PIN distinto por encargado.",13,Design.MUTED);}
  button("Actualizar mis permisos",()->task(()->auth.remote("status",new JSONObject()),r->{if(auth.authorized())dashboard();else pending();}));button("Bloquear y cambiar encargado",()->{StaffAccess.lock();login();});button("Volver al comedor",this::complete);
 }catch(Exception e){pending();}}
 static String role(String r){return r.equals("master")?"Usuario maestro":r.equals("admin")?"Administrador":"Encargado";}
 private void list(){task(()->{PeerConfig.require(auth.master(),"Solo el maestro administra cuentas.");return auth.remote("list",new JSONObject());},r->{try{
  screen("Encargados y permisos","Solo el usuario maestro crea, modifica y desactiva cuentas. Desactivar conserva las entregas anteriores.");button("Crear administrador o encargado",()->{editing=null;scan("grant");});button("Autorizar solicitud copiada",this::pasteRequest);
  JSONArray all=auth.users();for(int i=0;i<all.length();i++){JSONObject u=all.getJSONObject(i);if(u.getString("role").equals("master")){label(u.getString("name")+" · Maestro",17,Design.INK);continue;}button(u.getString("name")+" · "+role(u.getString("role"))+(u.optBoolean("active")?"":" · Desactivado"),()->form(u,null));}
  button("Volver",this::dashboard);
 }catch(Exception e){error(e.getMessage());}});}
 private void form(JSONObject existing,JSONObject request){try{
  PeerConfig.require(auth.master(),"Solo el maestro administra cuentas.");editing=existing;replaceId=request==null?"":request.getString("request");
  screen(existing==null?"Crear cuenta":"Editar cuenta","El permiso se limita a esta empresa. Para SOBOCE y FRIGOR se autoriza el mismo perfil en cada empresa.");
  EditText name=field("Nombre del encargado",existing==null?request.optString("name",""):existing.getString("name"),false);
  Spinner role=new Spinner(this);role.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Encargado","Administrador"}));role.setSelection(existing!=null&&existing.getString("role").equals("admin")?1:0);page.addView(role);
  label("PLANTAS AUTORIZADAS",13,Design.BLUE);List<CheckBox> plants=new ArrayList<>();JSONArray all=config.seed.getJSONArray("plants");for(int i=0;i<all.length();i++){CheckBox c=new CheckBox(this);c.setText(all.getString(i));c.setChecked(existing!=null?StaffProtocol.contains(existing.getJSONArray("plants"),all.getString(i)):all.length()==1);plants.add(c);page.addView(c);}
  label("El encargado siempre puede escanear, vincular obreros y consultar sus plantas. Permisos adicionales (el administrador recibe los tres):",14,Design.MUTED);List<CheckBox> extras=new ArrayList<>();String[] keys={"issue","worker","visitor"},titles={"Emitir e imprimir QR físicos","Crear nuevos trabajadores","Autorizar visitantes"};for(int i=0;i<keys.length;i++){CheckBox c=new CheckBox(this);c.setText(titles[i]);c.setTag(keys[i]);c.setChecked(existing!=null&&StaffProtocol.contains(existing.getJSONArray("permissions"),keys[i]));extras.add(c);page.addView(c);}
  CheckBox active=new CheckBox(this);active.setText("Cuenta habilitada");active.setChecked(existing==null||existing.getBoolean("active"));active.setEnabled(existing!=null);page.addView(active);
  if(!replaceId.isEmpty()&&existing!=null)label("Se reemplazará el teléfono anterior cuando guardes.",15,Design.RED);
  button("Guardar autorización",()->task(()->{PeerConfig.require(auth.master(),"Solo el maestro administra cuentas.");if(active.isChecked())QrPrintData.requirePermission(Companies.license(this,company));JSONArray ps=new JSONArray(),perms=new JSONArray();for(CheckBox c:plants)if(c.isChecked())ps.put(c.getText().toString());for(CheckBox c:extras)if(c.isChecked())perms.put(c.getTag().toString());JSONObject body=new JSONObject().put("name",name.getText().toString()).put("role",role.getSelectedItemPosition()==1?"admin":"encargado").put("plants",ps).put("permissions",perms).put("active",active.isChecked());
    if(existing!=null)body.put("id",existing.getString("id")).put("expected",existing.getLong("revision"));if(!replaceId.isEmpty())body.put("request",replaceId);return auth.remote(existing==null?"grant":"update",body);
   },r->{screen("Autorización guardada","El teléfono autorizado debe tocar Comprobar. Los equipos desconectados aplicarán los cambios al sincronizar.");button("Volver a las cuentas",this::list);}));
  if(existing!=null){button("Recuperar acceso · escanear solicitud",()->{editing=existing;scan("grant");});button("Recuperar acceso · pegar solicitud",()->pasteRequest(existing));}button("Cancelar",this::list);
 }catch(Exception e){error(e.getMessage());}}
 private void scan(String mode){try{PeerConfig.require(StaffAccess.session(auth.profile),"Desbloquea tu perfil.");if(mode.equals("grant"))PeerConfig.require(auth.master(),"Solo el maestro autoriza cuentas.");scanMode=mode;new IntentIntegrator(this).setCaptureActivity(bo.colbert.credential.CredentialScanActivity.class).setDesiredBarcodeFormats(IntentIntegrator.QR_CODE).setPrompt(mode.equals("master")?"Escanea tu activación o recuperación privada":"Escanea la solicitud del nuevo encargado").setBeepEnabled(false).setOrientationLocked(true).initiateScan();}catch(Exception e){error(e.getMessage());}}
 @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);IntentResult scan=IntentIntegrator.parseActivityResult(request,result,data);if(scan==null||scan.getContents()==null)return;readScan(scan.getContents());}
 private void readScan(String qr){try{
  PeerConfig.require(qr.length()<16000,"Código demasiado grande.");
  if(scanMode.equals("master")){PeerConfig.require(qr.startsWith(StaffProtocol.MASTER),"Este no es el código privado del maestro.");JSONObject b=new JSONObject(qr.substring(StaffProtocol.MASTER.length()));JSONArray companies=b.getJSONArray("companies");String code="";for(int i=0;i<companies.length();i++)if(companies.getJSONObject(i).getString("cluster").equals(config.cluster))code=companies.getJSONObject(i).getString("code");PeerConfig.require(!code.isEmpty(),"El código pertenece a otra empresa.");String secret=code,action=b.optString("kind").equals("recovery")?"recover":"claim";
   task(()->auth.remote(action,new JSONObject().put("code",secret).put("name",auth.local().getString("name")).put("device",config.device)),r->complete());
  }else{PeerConfig.require(qr.startsWith(StaffProtocol.REQUEST),"Escanea la solicitud del encargado, no el QR de un trabajador.");JSONObject r=new JSONObject(qr.substring(StaffProtocol.REQUEST.length()));PeerConfig.require(r.getString("cluster").equals(config.cluster)&&r.getLong("expires")>=System.currentTimeMillis(),"Solicitud vencida o de otra empresa.");JSONObject target=editing;
   task(()->auth.remote("list",new JSONObject()),reply->{try{JSONArray pending=reply.getJSONArray("pending");JSONObject found=null;for(int i=0;i<pending.length();i++)if(pending.getJSONObject(i).getString("id").equals(r.getString("request")))found=pending.getJSONObject(i);PeerConfig.require(found!=null,"La solicitud ya se utilizó o venció.");r.put("name",found.getString("name")).put("intent",found.optString("intent","new"));if(target!=null)form(target,r);else if(r.getString("intent").equals("recover"))chooseExisting(r);else{screen("Autorizar acceso",r.getString("name")+" · Si esta persona ya está registrada, recupera su cuenta existente para conservar su identificador.");button("Vincular a una cuenta existente",()->chooseExisting(r));button("Crear una cuenta nueva",()->form(null,r));button("Cancelar",this::list);}}catch(Exception e){error(e.getMessage());}});
  }
 }catch(Exception e){error(e.getMessage());}}
 private void copyRequest(String qr){android.content.ClipboardManager clipboard=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText("Solicitud de encargado",qr));state.setText("Solicitud copiada. El maestro puede usar Autorizar solicitud copiada; vence en diez minutos.");}
 private void chooseExisting(JSONObject request){try{PeerConfig.require(auth.master(),"Solo el maestro recupera cuentas.");screen("Elegir cuenta existente","Solicitud de "+request.getString("name")+". Confirma quién es antes de elegir su cuenta. Se conservarán su identificador, rol, plantas e historial; el acceso anterior quedará reemplazado al guardar.");JSONArray all=auth.users();int count=0;for(int i=0;i<all.length();i++){JSONObject u=all.getJSONObject(i);if(u.getString("role").equals("master"))continue;count++;button(u.getString("name")+" · "+role(u.getString("role"))+(u.getBoolean("active")?"":" · Desactivado"),()->form(u,request));}if(count==0)label("No hay cuentas de encargados o administradores en esta empresa. Comprueba la empresa seleccionada. El maestro utiliza su recuperación privada.",15,Design.MUTED);button("Cancelar",this::list);}catch(Exception e){error(e.getMessage());}}
 private void pasteRequest(){pasteRequest(null);}
 private void pasteRequest(JSONObject target){try{PeerConfig.require(auth.master(),"Solo el maestro autoriza cuentas.");android.content.ClipboardManager clipboard=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);ClipData clip=clipboard.getPrimaryClip();PeerConfig.require(clip!=null&&clip.getItemCount()>0,"Copia primero la solicitud del encargado.");String value=clip.getItemAt(0).coerceToText(this).toString();PeerConfig.require(value.startsWith(StaffProtocol.REQUEST),"El portapapeles no contiene una solicitud de encargado.");editing=target;scanMode="grant";readScan(value);}catch(Exception e){error(e.getMessage());}}
 private void shareRequest(String qr){try{BitMatrix m=new MultiFormatWriter().encode(qr,BarcodeFormat.QR_CODE,800,800);Bitmap b=Bitmap.createBitmap(800,800,Bitmap.Config.RGB_565);for(int y=0;y<800;y++)for(int x=0;x<800;x++)b.setPixel(x,y,m.get(x,y)?Color.BLACK:Color.WHITE);java.io.File folder=new java.io.File(getCacheDir(),"cards");folder.mkdirs();java.io.File file=new java.io.File(folder,"solicitud-encargado.png");try(java.io.FileOutputStream out=new java.io.FileOutputStream(file)){b.compress(Bitmap.CompressFormat.PNG,100,out);}Intent share=new Intent(Intent.ACTION_SEND).setType("image/png").putExtra(Intent.EXTRA_STREAM,androidx.core.content.FileProvider.getUriForFile(this,getPackageName()+".files",file)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(share,"Enviar solicitud al maestro"));}catch(Exception e){error("No se pudo compartir la solicitud.");}}
 private void showQr(String value)throws Exception {BitMatrix m=new MultiFormatWriter().encode(value,BarcodeFormat.QR_CODE,800,800);Bitmap bitmap=Bitmap.createBitmap(800,800,Bitmap.Config.RGB_565);for(int y=0;y<800;y++)for(int x=0;x<800;x++)bitmap.setPixel(x,y,m.get(x,y)?Color.BLACK:Color.WHITE);ImageView v=new ImageView(this);v.setImageBitmap(bitmap);v.setAdjustViewBounds(true);page.addView(v,new LinearLayout.LayoutParams(-1,600));}
 @Override protected void onDestroy(){if(biometric!=null)biometric.cancel();executor.shutdown();super.onDestroy();}
}
